import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

const user = { email: 'a@example.com', name: 'Alice', role: 'admin' as const };

describe('users API', () => {
  it('creates, gets, updates and deletes users', async () => {
    const app = createApp();
    const created = await request(app).post('/v1/users').send(user);
    expect(created.status).toBe(201);
    expect(created.headers.location).toMatch(/^\/v1\/users\//);
    expect(created.body).toMatchObject(user);
    const id = created.body.id as string;
    expect((await request(app).get(`/v1/users/${id}`)).status).toBe(200);
    const patched = await request(app).patch(`/v1/users/${id}`).send({ name: 'A' });
    expect(patched.status).toBe(200);
    expect(patched.body.name).toBe('A');
    expect((await request(app).delete(`/v1/users/${id}`)).status).toBe(204);
    expect((await request(app).get(`/v1/users/${id}`)).status).toBe(404);
  });

  it('defaults role and cursor paginates all users', async () => {
    const app = createApp();
    for (let i = 0; i < 5; i += 1) await request(app).post('/v1/users').send({ email: `u${i}@e.com`, name: `U${i}` });
    const ids: string[] = [];
    let cursor: string | undefined;
    do {
      const response = await request(app).get('/v1/users').query({ limit: 2, ...(cursor ? { cursor } : {}) });
      expect(response.status).toBe(200);
      ids.push(...(response.body.data as { id: string }[]).map((item) => item.id));
      cursor = response.body.nextCursor ?? undefined;
    } while (cursor);
    expect(ids).toHaveLength(5);
    expect(new Set(ids).size).toBe(5);
    expect((await request(app).get('/v1/users')).body.data[0].role).toBe('member');
  });

  it('validates fields, malformed JSON, missing resources and conflicts', async () => {
    const app = createApp();
    const invalid = await request(app).post('/v1/users').send({ email: 'bad', name: '' });
    expect(invalid.status).toBe(422);
    expect(invalid.headers['content-type']).toMatch(/application\/problem\+json/);
    expect(invalid.body.detail).toMatch(/email/);
    expect(invalid.body.detail).toMatch(/name/);
    expect((await request(app).post('/v1/users').set('Content-Type', 'application/json').send('{')).status).toBe(400);
    expect((await request(app).get('/v1/users').query({ limit: 101 })).status).toBe(422);
    expect((await request(app).get('/v1/users/not-a-uuid')).status).toBe(422);
    expect((await request(app).get('/v1/users/00000000-0000-4000-8000-000000000000')).status).toBe(404);
    await request(app).post('/v1/users').send(user);
    expect((await request(app).post('/v1/users').send(user)).status).toBe(409);
    expect((await request(app).patch('/v1/users/00000000-0000-4000-8000-000000000000').send({ name: 'x' })).status).toBe(404);
    expect((await request(app).patch('/v1/users/00000000-0000-4000-8000-000000000000').send({})).status).toBe(404);
  });

  it('replays idempotent creates and rejects changed bodies', async () => {
    const app = createApp();
    const first = await request(app).post('/v1/users').set('Idempotency-Key', 'key-1').send(user);
    const second = await request(app).post('/v1/users').set('Idempotency-Key', 'key-1').send(user);
    expect(second.status).toBe(201);
    expect(second.headers['idempotent-replayed']).toBe('true');
    expect(second.body.id).toBe(first.body.id);
    expect((await request(app).post('/v1/users').set('Idempotency-Key', 'key-1').send({ ...user, name: 'Other' })).status).toBe(422);
  });

  it('rejects empty patches and duplicate email changes', async () => {
    const app = createApp();
    const a = await request(app).post('/v1/users').send(user);
    const b = await request(app).post('/v1/users').send({ email: 'b@example.com', name: 'B' });
    expect((await request(app).patch(`/v1/users/${a.body.id}`).send({})).status).toBe(422);
    expect((await request(app).patch(`/v1/users/${b.body.id}`).send({ email: user.email })).status).toBe(409);
  });
});

import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';
import { idempotency } from '../lib/idempotency.ts';

const userSchema = z.object({ id: z.uuid(), email: z.email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']), createdAt: z.iso.datetime(), updatedAt: z.iso.datetime() });
const createSchema = z.object({ email: z.email(), name: z.string().min(1).max(100), role: z.enum(['admin', 'member']).default('member') });
const patchSchema = z.object({ email: z.email().optional(), name: z.string().min(1).max(100).optional(), role: z.enum(['admin', 'member']).optional() }).refine((v) => Object.keys(v).length > 0, 'at least one field is required');
const idSchema = z.object({ userId: z.uuid() });
const page = pageSchema(userSchema);
type User = z.infer<typeof userSchema>;

type Store = { users: User[] };
function parse<T>(schema: z.ZodType<T>, value: unknown): T { const result = schema.safeParse(value); if (!result.success) throw unprocessable(result.error.issues.map((i) => `${i.path.join('.') || 'request'}: ${i.message}`).join('; ')); return result.data; }
function routeError(next: NextFunction, error: unknown): void { next(error); }

export function registerRoutes(app: Router): void {
  const store: Store = { users: [] };
  const router = Router();
  router.post('/v1/users', idempotency(), (req: Request, res: Response, next: NextFunction) => { try { const input = parse(createSchema, req.body); if (store.users.some((u) => u.email === input.email)) throw conflict('email already exists'); const now = new Date().toISOString(); const user: User = { id: crypto.randomUUID(), ...input, createdAt: now, updatedAt: now }; store.users.push(user); userSchema.parse(user); res.status(201).location(`/v1/users/${user.id}`).json(user); } catch (e) { routeError(next, e); } });
  router.get('/v1/users', (req, res, next) => { try { const q = parse(CursorQuerySchema, req.query); const result = paginate(store.users, q, (u) => u.id); res.json(page.parse(result)); } catch (e) { routeError(next, e); } });
  router.get('/v1/users/:userId', (req, res, next) => { try { const { userId } = parse(idSchema, req.params); const user = store.users.find((u) => u.id === userId); if (!user) throw notFound('user not found'); res.json(userSchema.parse(user)); } catch (e) { routeError(next, e); } });
  router.patch('/v1/users/:userId', (req, res, next) => { try { const { userId } = parse(idSchema, req.params); const user = store.users.find((u) => u.id === userId); if (!user) throw notFound('user not found'); const input = parse(patchSchema, req.body); if (input.email && store.users.some((u) => u.id !== userId && u.email === input.email)) throw conflict('email already exists'); Object.assign(user, input, { updatedAt: new Date().toISOString() }); res.json(userSchema.parse(user)); } catch (e) { routeError(next, e); } });
  router.delete('/v1/users/:userId', (req, res, next) => { try { const { userId } = parse(idSchema, req.params); const index = store.users.findIndex((u) => u.id === userId); if (index < 0) throw notFound('user not found'); store.users.splice(index, 1); res.status(204).send(); } catch (e) { routeError(next, e); } });
  app.use(router);
}

import { randomUUID } from 'node:crypto';
import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import { CursorQuerySchema, paginate, pageSchema } from '../lib/pagination.ts';
import { conflict, notFound, unprocessable } from '../lib/problem.ts';
import { idempotency } from '../lib/idempotency.ts';

