 r.get('/:userId',(req,res,next)=>{try{res.json(UserSchema.parse(find(req)));}catch(e){next(e);}});
 r.patch('/:userId',idempotency(),(req,res,next)=>{try{const u=find(req);const p=PatchSchema.safeParse(req.body);if(!validation(next,p))return;if(p.data.email&&users.some(x=>x.email===p.data.email&&x.id!==u.id))throw conflict('email already exists');Object.assign(u,p.data,{updatedAt:new Date().toISOString()});res.json(UserSchema.parse(u));}catch(e){next(e);}});
