  router.patch('/v1/users/:userId', (req, res, next) => { try { const { userId } = parse(IdSchema, req.params); const user = users.find((u) => u.id === userId); if (!user) throw notFound('user not found'); const input = parse(PatchSchema, req.body); if (input.email && users.some((u) => u.id !== userId && u.email === input.email)) throw conflict('email already exists'); Object.assign(user, input, { updatedAt: new Date().toISOString() }); res.json(UserSchema.parse(user)); } catch (e) { next(e); } });
